func (r *TaskOffboardingResourceModel) ToSharedTaskServiceCreateOffboardingRequest(ctx context.Context) (*shared.TaskServiceCreateOffboardingRequest, diag.Diagnostics) {
	var diags diag.Diagnostics

	description := new(string)
	if !r.Description.IsUnknown() && !r.Description.IsNull() {
		*description = r.Description.ValueString()
	} else {
		description = nil
	}
	subjectUserID := new(string)
	if !r.SubjectUserID.IsUnknown() && !r.SubjectUserID.IsNull() {
		*subjectUserID = r.SubjectUserID.ValueString()
	} else {
		subjectUserID = nil
	}
	out := shared.TaskServiceCreateOffboardingRequest{
		Description:   description,
		SubjectUserID: subjectUserID,
	}

	return &out, diags
}
